import{_t as e,it as t,n,rt as r}from"./chunks/framework.BM2esBXZ.js";var i=JSON.parse(`{"title":"框架概述","description":"","frontmatter":{},"headers":[],"relativePath":"overview.md","filePath":"overview.md","lastUpdated":1793821509000}`),a={name:`overview.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="框架概述" tabindex="-1">框架概述 <a class="header-anchor" href="#框架概述" aria-label="Permalink to “框架概述”">​</a></h1><p>本页说明 XiHan Framework 的设计原则、环层与依赖规则、一次调用的执行路径、命名约定、稳定性分级与环境要求，供做技术评估与写扩展的读者参考。</p><h2 id="三层承诺" tabindex="-1">三层承诺 <a class="header-anchor" href="#三层承诺" aria-label="Permalink to “三层承诺”">​</a></h2><p>框架按变化速度把代码分成三层，每层给出不同的兼容承诺：</p><table tabindex="0"><thead><tr><th>层</th><th>范围</th><th>承诺</th></tr></thead><tbody><tr><td>原语层</td><td><code>XiHan.Framework.Primitives</code>（Ring 0）</td><td>只增不改，跨大版本不破坏；必须破坏时发布新包 ID <code>Primitives.V2</code> 并存</td></tr><tr><td>内核</td><td><code>XiHan.Framework.Kernel</code>（Ring 1）</td><td>大版本内不破坏</td></tr><tr><td>子系统与其上</td><td>抽象、实现、宿主、协议、插件、组合包（Ring 2–6）</td><td>各自演进，通过同一套一致性套件即视为兼容</td></tr></tbody></table><h2 id="设计原则" tabindex="-1">设计原则 <a class="header-anchor" href="#设计原则" aria-label="Permalink to “设计原则”">​</a></h2><table tabindex="0"><thead><tr><th>原则</th><th>落在代码里的规则</th></tr></thead><tbody><tr><td>内核克制</td><td>内核只定义宿主、能力图谱、管道、诊断、安全原语、操作契约与插件抽象，不含任何子系统实现</td></tr><tr><td>装配显式</td><td>服务在特性的 <code>Configure</code> 里显式注册；源生成器产出的登记代码也要显式调用（<code>AddGeneratedOperations</code>、<code>AddGeneratedRepositories</code>），不扫描程序集</td></tr><tr><td>依赖按能力声明</td><td>清单按能力 ID 与接口版本声明依赖，内核求解后打印已解析图，缺失、循环、版本冲突、多候选都在启动期报错</td></tr><tr><td>边界刚、内部柔</td><td>依赖方向、同环只经抽象包往来、抽象包不暴露第三方类型，全部由架构测试执行；包内实现可以随时重构</td></tr><tr><td>宿主落地</td><td>管道不绑定 HTTP；ASP.NET Core、命令行、消息消费、作业与插件回调走同一条管道</td></tr><tr><td>规范先于实现</td><td>公开契约先进 XiHan Spec 的 RFC，再写 ADR、代码与一致性向量</td></tr><tr><td>默认实现必须可用</td><td>每个抽象配一个零外部依赖、容量有界、通过一致性套件的默认实现，只在没有显式 Provider 时被选中</td></tr></tbody></table><h2 id="环层与依赖规则" tabindex="-1">环层与依赖规则 <a class="header-anchor" href="#环层与依赖规则" aria-label="Permalink to “环层与依赖规则”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ring 6  组合包          Profiles.Minimal / Standard / Full</span></span>
<span class="line"><span>Ring 5  协议与插件      Protocols.* / Plugins.InProcess / OutOfProcess / Wasm</span></span>
<span class="line"><span>Ring 4  宿主            Hosting.AspNetCore / Hosting.CommandLine</span></span>
<span class="line"><span>Ring 3  实现            &lt;领域&gt;.InMemory、&lt;领域&gt;.Database、Redis、EntityFrameworkCore 等</span></span>
<span class="line"><span>Ring 2  抽象            Domain、&lt;领域&gt;.Abstractions</span></span>
<span class="line"><span>Ring 1  内核            Kernel</span></span>
<span class="line"><span>Ring 0  原语层          Primitives</span></span>
<span class="line"><span>工具链                  Kernel.Analyzers、Kernel.Generators、Persistence.Generators、</span></span>
<span class="line"><span>                        &lt;领域&gt;.Conformance、Testing、Cli</span></span></code></pre></div><ol><li>只能依赖更低的环；同环之间只能引用对方的抽象包（<code>.Abstractions</code>，以及纯契约的 <code>Domain</code>）。</li><li>原语层不引用任何包；内核与全部抽象包只允许 <code>Microsoft.Extensions.*</code> 抽象包，内核另加 <code>System.Threading.RateLimiting</code>。</li><li>抽象包不暴露第三方类型，Provider 不被任何抽象包引用。</li><li>宿主与协议包不含业务规则；插件不被任何正式包引用。</li><li>原语层与内核零反射；反射只允许出现在 <code>Plugins.InProcess</code>，并标注 <code>RequiresDynamicCode</code>。</li><li>工具链可以引用任何环。</li></ol><p>规则由 <code>framework/test/XiHan.Framework.Architecture.Tests</code> 执行，违反即 CI 失败。</p><h2 id="一次调用的路径" tabindex="-1">一次调用的路径 <a class="header-anchor" href="#一次调用的路径" aria-label="Permalink to “一次调用的路径”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HTTP 请求 / gRPC 调用 / MCP tools/call / 命令行 / 消息投递 / 作业触发 / 插件回调</span></span>
<span class="line"><span>   │  协议适配器或派发器构造 InvocationContext，把线上消息翻译成操作请求</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>Ingress → Observe → Resilience → Authenticate → Tenant → Authorize</span></span>
<span class="line"><span>        → Validate → Idempotency → Transaction → Handle → Egress</span></span>
<span class="line"><span>   │  Handle 阶段执行操作，操作经子系统抽象访问 Provider</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>Egress：Result 与 Error 翻译回协议（HTTP 为 RFC 9457 Problem Details，gRPC 为状态码与尾部元数据）</span></span></code></pre></div><p>调用上下文 <code>InvocationContext</code> 携带取消令牌、截止时间、W3C Trace、已登记的 Baggage 键（租户、主体、关联 ID、幂等键、区域）、作用域对象袋与作用域服务。安全上下文（主体、租户）由 Authenticate 与 Tenant 阶段写入，之后不可变。</p><h2 id="命名约定" tabindex="-1">命名约定 <a class="header-anchor" href="#命名约定" aria-label="Permalink to “命名约定”">​</a></h2><p>命名由 XiHan Spec 的术语表推出，架构测试校验：</p><table tabindex="0"><thead><tr><th>对象</th><th>规则</th><th>示例</th></tr></thead><tbody><tr><td>包 ID</td><td><code>XiHan.Framework.&lt;领域&gt;[.&lt;角色&gt;]</code>，角色是 <code>Abstractions</code>、<code>Conformance</code>、<code>Generators</code> 或机制、技术名</td><td><code>XiHan.Framework.Caching.Redis</code></td></tr><tr><td>命名空间</td><td>等于包 ID，子命名空间最多一层</td><td><code>XiHan.Framework.Caching.Abstractions.Locking</code></td></tr><tr><td>能力 ID</td><td><code>&lt;领域小写&gt;.&lt;能力&gt;</code>，引用时带接口版本</td><td><code>caching.distributed@1</code></td></tr><tr><td>清单 ID</td><td><code>xihan.&lt;领域&gt;.&lt;名称&gt;</code></td><td><code>xihan.caching.redis</code></td></tr><tr><td>配置节</td><td><code>XiHan:&lt;领域&gt;</code></td><td><code>XiHan:Caching</code></td></tr><tr><td>错误码</td><td><code>&lt;领域大写&gt;_&lt;KIND&gt;_&lt;三位序号&gt;</code></td><td><code>PERSISTENCE_CONFLICT_001</code></td></tr><tr><td>操作 ID</td><td><code>&lt;资源复数&gt;.&lt;动词&gt;</code></td><td><code>orders.create</code></td></tr><tr><td>消息键</td><td><code>&lt;领域&gt;.&lt;资源&gt;.&lt;键&gt;</code></td><td><code>security.token.subject_missing</code></td></tr></tbody></table><p>类型名不带 <code>XiHan</code> 前缀；<code>Default</code>、<code>Core</code>、<code>Common</code>、<code>Manager</code>、<code>Helper</code> 等词不进包名与领域名；默认实现按机制命名（<code>InMemory</code>、<code>FileSystem</code>、<code>Database</code>），默认是清单里的 <code>role</code>，不是包名。</p><h2 id="核心机制速览" tabindex="-1">核心机制速览 <a class="header-anchor" href="#核心机制速览" aria-label="Permalink to “核心机制速览”">​</a></h2><table tabindex="0"><thead><tr><th>机制</th><th>一句话</th><th>详见</th></tr></thead><tbody><tr><td>特性与清单</td><td><code>IFeature</code> + <code>Manifest</code>，<code>UseFeature&lt;T&gt;()</code> 显式组合</td><td><a href="./guide/modularity">能力包与清单</a></td></tr><tr><td>生命周期</td><td>九态状态机，探针直接映射应用状态</td><td><a href="./guide/lifecycle">生命周期与健康</a></td></tr><tr><td>执行管道</td><td>十一个固定阶段，中间件按阶段插入</td><td><a href="./guide/pipeline">执行管道</a></td></tr><tr><td>操作契约</td><td><code>[Operation]</code> + <code>IOperation&lt;TRequest, TResponse&gt;</code>，一份契约多协议</td><td><a href="./guide/operations">操作契约</a></td></tr><tr><td>结果与错误</td><td><code>Result</code> / <code>Error</code> 代替异常表达可恢复失败，错误只带消息键</td><td><a href="./guide/errors">结果与错误</a></td></tr><tr><td>本地化</td><td>每种语言一个 JSON 文件，宿主按调用方区域翻译</td><td><a href="./guide/localization">国际化</a></td></tr><tr><td>默认实现与 Provider</td><td>抽象包 + 默认实现 + Provider，按能力选择</td><td><a href="./packages/">包总览</a></td></tr><tr><td>一致性套件</td><td>默认实现与 Provider 通过同一套行为测试</td><td><a href="./guide/testing">测试与一致性套件</a></td></tr></tbody></table><h2 id="稳定性分级" tabindex="-1">稳定性分级 <a class="header-anchor" href="#稳定性分级" aria-label="Permalink to “稳定性分级”">​</a></h2><p>公开类型都带 <code>[ApiLevel(Stability, &lt;引入版本&gt;)]</code>，公开面以各包的 <code>PublicAPI.Shipped.txt</code> 与 <code>PublicAPI.Unshipped.txt</code> 为准：</p><table tabindex="0"><thead><tr><th>级别</th><th>含义</th></tr></thead><tbody><tr><td><code>Stable</code></td><td>大版本内不破坏</td></tr><tr><td><code>Preview</code></td><td>可能变更</td></tr><tr><td><code>Experimental</code></td><td>可能移除，用于收集反馈（如 <code>Plugins.Wasm</code>、<code>Caching.Remote</code>）</td></tr><tr><td><code>Internal</code></td><td>不对外承诺，分析器阻止外部引用</td></tr><tr><td><code>Deprecated</code></td><td>将在下一个大版本移除</td></tr></tbody></table><p>弃用按规范的流程进行：先标 <code>Deprecated</code> 并以 <code>[Obsolete]</code> 给出警告与迁移说明，至少保留两个小版本；下一个大版本前升级为编译错误，大版本时移除。</p><h2 id="版本与兼容" tabindex="-1">版本与兼容 <a class="header-anchor" href="#版本与兼容" aria-label="Permalink to “版本与兼容”">​</a></h2><ul><li>全部包共享一条版本线。</li><li>目标框架 <code>net10.0</code>；版本号遵循 SemVer 2.0。</li><li>每个子系统的 Provider 接口单独版本化（<code>persistence.relational@1</code>），接口变更只加新版本并存。</li></ul><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to “环境要求”">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>要求</th></tr></thead><tbody><tr><td>SDK</td><td>.NET 10 SDK；构建框架源码时使用仓库 <code>global.json</code> 锁定的 10.0.4xx 功能带</td></tr><tr><td>测试运行器</td><td>Microsoft.Testing.Platform（由 <code>global.json</code> 启用，<code>dotnet test</code> 用 <code>--solution</code> 或 <code>--project</code>）</td></tr><tr><td>操作系统</td><td>Windows、Linux、macOS；Wasm 插件宿主在 Windows 上要求宿主可执行项目设置 <code>CETCompat=false</code></td></tr><tr><td>外部设施</td><td>默认实现不需要；Provider 按各自包页的说明</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./quickstart">快速上手</a>：取得预览包，写第一个操作</li><li><a href="./why">为什么选择曦寒</a>：适用场景与代价</li><li><a href="./guide/modularity">开发指南</a>：从能力包与清单开始</li></ul>`,30)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};